import { useState, useEffect } from 'react';
import { collection, getDocs, addDoc, updateDoc, deleteDoc, doc, query, where, orderBy, serverTimestamp, onSnapshot, writeBatch } from 'firebase/firestore';
import { db } from '../../firebase';
import { useNotification } from './NotificationSystem';
import { 
  FiPlus, FiEdit2, FiTrash2, FiCalendar, FiFilter, FiRefreshCw,
  FiUser, FiMapPin, FiFlag, FiCheckCircle, FiClock, FiUsers,
  FiTarget, FiTrendingUp, FiActivity, FiSearch, FiX, FiPackage,
  FiFileText, FiTool, FiCpu, FiZap, FiPlay, FiCheck, FiTruck
} from 'react-icons/fi';
import TodoItem from './TodoItem';
import AddTodoModal from './AddTodoModal';
import EditTodoModal from './EditTodoModal';

// Machine operations mapping (consistent with StatusManager)
const MACHINE_OPERATIONS = {
  HBL: { name: 'Horizontal Boring', icon: FiTool, color: 'bg-blue-100 text-blue-800' },
  VTL: { name: 'Vertical Turning', icon: FiCpu, color: 'bg-purple-100 text-purple-800' },
  Drilling: { name: 'Drilling', icon: FiZap, color: 'bg-green-100 text-green-800' },
  VMC: { name: 'Vertical Machining', icon: FiTarget, color: 'bg-indigo-100 text-indigo-800' }
};

export default function VendorTodoList() {
  const { showSuccess, showError } = useNotification();
  
  const [vendors, setVendors] = useState([]);
  const [todoItems, setTodoItems] = useState([]);
  const [autoGeneratedTodos, setAutoGeneratedTodos] = useState([]);
  const [completedOperations, setCompletedOperations] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [statusFilter, setStatusFilter] = useState('all');
  const [operationFilter, setOperationFilter] = useState('all');
  const [viewMode, setViewMode] = useState('all');
  const [showCompleted, setShowCompleted] = useState(true);
  
  // Operation types (matching StatusManager operations)
  const operationTypes = [
    { value: 'hbl', label: 'Horizontal Boring', color: 'bg-blue-100 text-blue-800', icon: FiTool },
    { value: 'vtl', label: 'Vertical Turning', color: 'bg-purple-100 text-purple-800', icon: FiCpu },
    { value: 'drilling', label: 'Drilling', color: 'bg-green-100 text-green-800', icon: FiZap },
    { value: 'vmc', label: 'Vertical Machining', color: 'bg-indigo-100 text-indigo-800', icon: FiTarget },
    { value: 'grinding', label: 'Grinding', color: 'bg-orange-100 text-orange-800', icon: FiTool },
    { value: 'assembly', label: 'Assembly', color: 'bg-indigo-100 text-indigo-800', icon: FiTool },
    { value: 'painting', label: 'Painting', color: 'bg-pink-100 text-pink-800', icon: FiTool },
    { value: 'packing', label: 'Packing', color: 'bg-teal-100 text-teal-800', icon: FiPackage },
    { value: 'other', label: 'Other', color: 'bg-gray-100 text-gray-800', icon: FiTool }
  ];
  
  const priorities = [
    { value: 'high', label: 'High Priority', color: 'bg-red-100 text-red-800' },
    { value: 'medium', label: 'Medium Priority', color: 'bg-yellow-100 text-yellow-800' },
    { value: 'low', label: 'Low Priority', color: 'bg-green-100 text-green-800' }
  ];

  const statuses = [
    { value: 'pending', label: 'Pending', color: 'bg-gray-100 text-gray-800', icon: FiClock },
    { value: 'in-progress', label: 'In Progress', color: 'bg-blue-100 text-blue-800', icon: FiPlay },
    { value: 'completed', label: 'Completed', color: 'bg-green-100 text-green-800', icon: FiCheckCircle },
    { value: 'cancelled', label: 'Cancelled', color: 'bg-red-100 text-red-800', icon: FiX }
  ];

  const [formData, setFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    vendors: [{ vendorId: '', bodiesCount: 1 }],
    operationType: 'hbl',
    targetLocation: 'VMT Store',
    notes: '',
    status: 'pending',
    priority: 'medium',
    source: 'manual'
  });

  // Fetch completed operations from purchase orders (matching StatusManager logic)
  const fetchCompletedOperations = async () => {
    try {
      const posQuery = query(collection(db, 'purchaseOrders'));
      const snapshot = await getDocs(posQuery);
      
      const completedOps = [];
      
      snapshot.forEach(doc => {
        const poData = { id: doc.id, ...doc.data() };
        const operationsStatus = poData.operationsStatus || {};
        
        // Check each item's operations for completed status
        Object.entries(operationsStatus).forEach(([itemIndex, itemOperations]) => {
          Object.entries(itemOperations).forEach(([operation, status]) => {
            if (status === 'completed') {
              const itemDescription = poData.items?.[parseInt(itemIndex)]?.description || `Item ${parseInt(itemIndex) + 1}`;
              
              completedOps.push({
                poId: poData.id,
                poNumber: poData.poNumber,
                vendorId: poData.vendorId,
                vendorName: poData.vendorName || poData.vendor || 'Unknown Vendor',
                operation: operation,
                itemIndex: parseInt(itemIndex),
                itemDescription: itemDescription,
                quantity: poData.items?.[parseInt(itemIndex)]?.quantity || 1,
                unit: poData.items?.[parseInt(itemIndex)]?.unit || 'pcs',
                completedAt: poData.operationsMeta?.[`${itemIndex}_${operation}`]?.completedAt || poData.updatedAt,
                createdAt: poData.createdAt,
                vendorTodoCreated: poData.operationsMeta?.[`${itemIndex}_${operation}`]?.vendorTodoCreated || false,
                vendorTodoId: poData.operationsMeta?.[`${itemIndex}_${operation}`]?.vendorTodoId || null
              });
            }
          });
        });
      });
      
      setCompletedOperations(completedOps);
      return completedOps;
    } catch (error) {
      console.error('Error fetching completed operations:', error);
      showError('Failed to load completed operations');
      return [];
    }
  };

  // Auto-create vendor todo for completed operations
  const autoCreateVendorTodos = async (completedOps) => {
    try {
      const batch = writeBatch(db);
      const createdTodos = [];
      const opsToUpdate = [];
      
      for (const op of completedOps) {
        // Skip if todo already created
        if (op.vendorTodoCreated) continue;
        
        // Check if todo already exists
        const existingTodoQuery = query(
          collection(db, 'vendorTodos'),
          where('poId', '==', op.poId),
          where('operation', '==', op.operation),
          where('itemIndex', '==', op.itemIndex)
        );
        
        const existingSnapshot = await getDocs(existingTodoQuery);
        
        if (!existingSnapshot.empty) {
          // Mark as created but don't create new one
          opsToUpdate.push({ ...op, vendorTodoId: existingSnapshot.docs[0].id });
          continue;
        }

        // Create deterministic ID for the todo
        const dateKey = new Date().toISOString().slice(0, 10);
        const todoId = `todo_${op.poId}_${op.itemIndex}_${op.operation}_collect_${dateKey}`;
        const todoRef = doc(db, 'vendorTodos', todoId);
        
        const opLower = (op.operation || '').toString().toLowerCase();
        const allowedOps = ['hbl', 'vtl', 'drilling', 'vmc', 'grinding', 'assembly', 'painting', 'packing', 'other'];
        const operationType = allowedOps.includes(opLower) ? opLower : 'other';

        const todoData = {
          id: todoId,
          date: dateKey,
          vendors: op.vendorId ? [{ vendorId: op.vendorId, bodiesCount: op.quantity || 1 }] : [],
          totalBodies: op.quantity || 1,
          operationType: operationType,
          targetLocation: 'VMT Store',
          notes: `Collect material for ${MACHINE_OPERATIONS[op.operation]?.name || op.operation} - ${op.itemDescription} (PO ${op.poNumber})`,
          status: 'pending',
          priority: 'high',
          createdAt: serverTimestamp(),
          updatedAt: serverTimestamp(),
          // Linkage fields
          vendorId: op.vendorId || null,
          vendorName: op.vendorName || null,
          poId: op.poId,
          poNumber: op.poNumber,
          operation: op.operation,
          itemIndex: op.itemIndex,
          itemDescription: op.itemDescription,
          source: 'statusManager',
          autoGenerated: true,
        };

        batch.set(todoRef, todoData, { merge: true });
        createdTodos.push({ id: todoId, ...todoData });
        opsToUpdate.push({ ...op, vendorTodoId: todoId });
      }
      
      // Update purchase order operationsMeta to mark todos as created
      for (const op of opsToUpdate) {
        const poRef = doc(db, 'purchaseOrders', op.poId);
        const operationKey = `${op.itemIndex}_${op.operation}`;
        
        batch.update(poRef, {
          [`operationsMeta.${operationKey}.vendorTodoCreated`]: true,
          [`operationsMeta.${operationKey}.vendorTodoId`]: op.vendorTodoId,
          [`operationsMeta.${operationKey}.updatedAt`]: serverTimestamp(),
        });
      }
      
      if (createdTodos.length > 0 || opsToUpdate.length > 0) {
        await batch.commit();
        showSuccess(`Processed ${createdTodos.length + opsToUpdate.length} completed operations`);
        fetchTodos();
      }
      
      return createdTodos;
    } catch (error) {
      console.error('Error auto-creating vendor todos:', error);
      showError('Failed to create automatic collection tasks');
      throw error;
    }
  };

  // Load vendors and todos
  const fetchData = async () => {
    try {
      setLoading(true);
      
      // Vendors
      const vendorsSnapshot = await getDocs(collection(db, 'vendors'));
      const vendorsData = vendorsSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setVendors(vendorsData);

      // Fetch completed operations and auto-create todos
      const completedOpsData = await fetchCompletedOperations();
      if (completedOpsData.length > 0) {
        await autoCreateVendorTodos(completedOpsData.filter(op => !op.vendorTodoCreated));
      }

      await fetchTodos();
    } catch (error) {
      console.error('Error fetching data:', error);
      showError('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  // Set up real-time listener for purchase orders (to detect new completed operations)
  const setupPurchaseOrdersListener = () => {
    try {
      const q = query(collection(db, 'purchaseOrders'));
      
      return onSnapshot(q, async (snapshot) => {
        const completedOps = [];
        
        snapshot.forEach(doc => {
          const poData = { id: doc.id, ...doc.data() };
          const operationsStatus = poData.operationsStatus || {};
          
          Object.entries(operationsStatus).forEach(([itemIndex, itemOperations]) => {
            Object.entries(itemOperations).forEach(([operation, status]) => {
              if (status === 'completed') {
                const itemDescription = poData.items?.[parseInt(itemIndex)]?.description || `Item ${parseInt(itemIndex) + 1}`;
                
                completedOps.push({
                  poId: poData.id,
                  poNumber: poData.poNumber,
                  vendorId: poData.vendorId,
                  vendorName: poData.vendorName || poData.vendor || 'Unknown Vendor',
                  operation: operation,
                  itemIndex: parseInt(itemIndex),
                  itemDescription: itemDescription,
                  quantity: poData.items?.[parseInt(itemIndex)]?.quantity || 1,
                  vendorTodoCreated: poData.operationsMeta?.[`${itemIndex}_${operation}`]?.vendorTodoCreated || false,
                });
              }
            });
          });
        });
        
        const newCompletedOps = completedOps.filter(op => !op.vendorTodoCreated);
        if (newCompletedOps.length > 0) {
          await autoCreateVendorTodos(newCompletedOps);
        }
      });
    } catch (error) {
      console.error('Error setting up purchase orders listener:', error);
      return null;
    }
  };

  // Set up real-time listener for auto-generated todos
  const setupAutoTodosListener = () => {
    try {
      const q = query(
        collection(db, 'vendorTodos'),
        where('autoGenerated', '==', true),
        orderBy('createdAt', 'desc')
      );
      
      return onSnapshot(q, (snapshot) => {
        const autoTodos = [];
        snapshot.forEach(doc => {
          autoTodos.push({
            id: doc.id,
            ...doc.data()
          });
        });
        setAutoGeneratedTodos(autoTodos);
      });
    } catch (error) {
      console.error('Error setting up auto-todos listener:', error);
      return null;
    }
  };

  // Fetch manual todos for selected date
  const fetchTodos = async () => {
    try {
      const q = query(
        collection(db, 'vendorTodos'),
        where('date', '==', selectedDate),
        where('autoGenerated', '==', false),
        orderBy('createdAt', 'desc')
      );
      
      const snapshot = await getDocs(q);
      const todosData = snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      }));
      
      setTodoItems(todosData);
    } catch (error) {
      console.error('Error fetching todos:', error);
      // This might fail if no index exists, so we'll handle it gracefully
      if (error.code === 'failed-precondition') {
        console.log('Index needed for date query, fetching all todos instead');
        const allSnapshot = await getDocs(collection(db, 'vendorTodos'));
        const allTodos = allSnapshot.docs
          .map(doc => ({ id: doc.id, ...doc.data() }))
          .filter(todo => todo.date === selectedDate && !todo.autoGenerated);
        setTodoItems(allTodos);
      } else {
        showError('Failed to fetch todos');
      }
    }
  };

  useEffect(() => {
    fetchData();
    
    const unsubscribePOs = setupPurchaseOrdersListener();
    const unsubscribeAutoTodos = setupAutoTodosListener();
    
    return () => {
      if (unsubscribePOs) unsubscribePOs();
      if (unsubscribeAutoTodos) unsubscribeAutoTodos();
    };
  }, [selectedDate]);

  // Combine manual and auto-generated todos based on view mode
  const getCombinedTodos = () => {
    switch (viewMode) {
      case 'manual':
        return todoItems;
      case 'auto':
        return autoGeneratedTodos.filter(todo => 
          !selectedDate || todo.date === selectedDate
        );
      case 'all':
      default:
        const allTodos = [
          ...todoItems,
          ...autoGeneratedTodos.filter(todo => 
            !selectedDate || todo.date === selectedDate
          )
        ];
        // Remove duplicates by ID
        return allTodos.filter((todo, index, self) =>
          index === self.findIndex(t => t.id === todo.id)
        );
    }
  };

  // Filter todos based on status and operation
  const filteredTodos = getCombinedTodos().filter(todo => {
    let statusMatch = true;
    let operationMatch = true;
    
    if (statusFilter !== 'all') {
      statusMatch = todo.status === statusFilter;
    }
    
    if (operationFilter !== 'all') {
      operationMatch = todo.operationType === operationFilter;
    }
    
    return statusMatch && operationMatch;
  });

  // Split into active and completed groups
  const activeTodos = filteredTodos.filter(t => t.status !== 'completed');
  const completedTodos = filteredTodos.filter(t => t.status === 'completed');

  // Add a vendor to the form
  const addVendorField = () => {
    setFormData({
      ...formData,
      vendors: [...formData.vendors, { vendorId: '', bodiesCount: 1 }]
    });
  };

  // Remove a vendor from the form
  const removeVendorField = (index) => {
    const updatedVendors = [...formData.vendors];
    updatedVendors.splice(index, 1);
    setFormData({
      ...formData,
      vendors: updatedVendors
    });
  };

  // Update vendor field
  const updateVendorField = (index, field, value) => {
    const updatedVendors = [...formData.vendors];
    updatedVendors[index][field] = value;
    setFormData({
      ...formData,
      vendors: updatedVendors
    });
  };

  const handleAddTodo = async (e) => {
    e.preventDefault();
    
    try {
      const totalBodies = formData.vendors.reduce((sum, vendor) => sum + parseInt(vendor.bodiesCount || 1), 0);
      
      const todoData = {
        ...formData,
        vendors: formData.vendors.map(vendor => ({
          ...vendor,
          vendorName: getVendorName(vendor.vendorId)
        })),
        totalBodies,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
        autoGenerated: false,
        source: 'manual'
      };
      
      await addDoc(collection(db, 'vendorTodos'), todoData);
      
      setFormData({
        date: new Date().toISOString().split('T')[0],
        vendors: [{ vendorId: '', bodiesCount: 1 }],
        operationType: 'hbl',
        targetLocation: 'VMT Store',
        notes: '',
        status: 'pending',
        priority: 'medium',
        source: 'manual'
      });
      
      setShowAddModal(false);
      fetchTodos();
      showSuccess('Resource plan added successfully');
    } catch (error) {
      console.error('Error adding todo:', error);
      showError('Failed to add resource plan');
    }
  };

  const handleUpdateTodo = async (todoId, updates) => {
    try {
      const todoRef = doc(db, 'vendorTodos', todoId);
      const payload = { ...updates, updatedAt: serverTimestamp() };

      await updateDoc(todoRef, payload);
      showSuccess('Todo updated successfully');
      fetchTodos();
    } catch (error) {
      console.error('Error updating todo:', error);
      showError('Failed to update todo');
    }
  };

  // Quick action: Mark as 'Go' (start collection)
  const handleMarkGo = async (item) => {
    try {
      await updateDoc(doc(db, 'vendorTodos', item.id), {
        status: 'in-progress',
        goAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
      });
      showSuccess('Marked as going to vendor for pickup');
      fetchTodos();
    } catch (error) {
      console.error('Error marking go:', error);
      showError('Failed to mark as go');
    }
  };

  // Quick action: Mark as 'Picked Up' (complete collection)
  const handleMarkPickedUp = async (item) => {
    try {
      const batch = writeBatch(db);
      
      // Update the todo
      batch.update(doc(db, 'vendorTodos', item.id), {
        status: 'completed',
        pickedUpAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
      });
      
      // If it's auto-generated from a PO operation, update the PO as well
      if (item.autoGenerated && item.poId && item.operation && item.itemIndex !== undefined) {
        const poRef = doc(db, 'purchaseOrders', item.poId);
        const operationKey = `${item.itemIndex}_${item.operation}`;
        
        batch.update(poRef, {
          [`operationsMeta.${operationKey}.materialCollected`]: true,
          [`operationsMeta.${operationKey}.collectedAt`]: serverTimestamp(),
          [`operationsMeta.${operationKey}.updatedAt`]: serverTimestamp(),
        });
      }
      
      await batch.commit();
      showSuccess('Marked as picked up and job status updated');
      fetchTodos();
    } catch (error) {
      console.error('Error marking picked up:', error);
      showError('Failed to mark as picked up');
    }
  };

  const handleDeleteTodo = async (todoId) => {
    if (!window.confirm('Are you sure you want to delete this todo item?')) {
      return;
    }

    try {
      await deleteDoc(doc(db, 'vendorTodos', todoId));
      showSuccess('Todo deleted successfully');
      fetchTodos();
    } catch (error) {
      console.error('Error deleting todo:', error);
      showError('Failed to delete todo');
    }
  };

  const getVendorName = (vendorId) => {
    const vendor = vendors.find(v => v.id === vendorId);
    return vendor ? vendor.name : 'Unknown Vendor';
  };

  const getStatusInfo = (status) => {
    return statuses.find(s => s.value === status) || statuses[0];
  };

  const getPriorityInfo = (priority) => {
    return priorities.find(p => p.value === priority) || priorities[1];
  };

  const getOperationInfo = (operationType) => {
    return operationTypes.find(op => op.value === operationType) || operationTypes[0];
  };

  const getMachineOperationName = (operation) => {
    return MACHINE_OPERATIONS[operation]?.name || operation;
  };

  // Manual trigger to create todos from completed operations
  const handleCreateTodosFromCompletedOps = async () => {
    try {
      const ops = await fetchCompletedOperations();
      const newOps = ops.filter(op => !op.vendorTodoCreated);
      
      if (newOps.length > 0) {
        await autoCreateVendorTodos(newOps);
      } else {
        showSuccess('No new completed operations found');
      }
    } catch (error) {
      console.error('Error creating todos from completed operations:', error);
      showError('Failed to create collection tasks');
    }
  };

  const getTodayStats = () => {
    const combined = getCombinedTodos();
    const totalBodies = combined.reduce((sum, item) => sum + (item.totalBodies || 0), 0);
    const completedItems = combined.filter(item => item.status === 'completed').length;
    const pendingItems = combined.filter(item => item.status === 'pending').length;
    const inProgressItems = combined.filter(item => item.status === 'in-progress').length;
    const autoGeneratedCount = autoGeneratedTodos.filter(todo => 
      !selectedDate || todo.date === selectedDate
    ).length;
    const manualCount = todoItems.length;

    return { totalBodies, completedItems, pendingItems, inProgressItems, autoGeneratedCount, manualCount };
  };

  const stats = getTodayStats();

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      {loading ? (
        <div className="flex justify-center items-center h-64">
          <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-indigo-500"></div>
        </div>
      ) : (
        <div className="max-w-7xl mx-auto space-y-6">
          {/* Header */}
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200">
            <div className="flex justify-between items-center">
              <div className="flex items-center space-x-3">
                <div className="w-10 h-10 bg-gradient-to-br from-purple-500 to-indigo-600 rounded-xl flex items-center justify-center">
                  <FiTruck className="text-white" size={20} />
                </div>
                <div>
                  <h1 className="text-2xl font-bold text-gray-900">Vendor Material Collection</h1>
                  <p className="text-gray-600">Manage vendor resource allocation and material collection from completed jobs</p>
                </div>
              </div>
              <div className="flex space-x-3">
                <button
                  onClick={handleCreateTodosFromCompletedOps}
                  className="inline-flex items-center px-4 py-3 bg-gradient-to-r from-green-500 to-emerald-600 text-white font-medium rounded-xl hover:from-green-600 hover:to-emerald-700 transition-all duration-200 shadow-sm hover:shadow-md"
                >
                  <FiCheckCircle className="mr-2" size={16} />
                  Sync Completed Jobs
                </button>
                <button
                  onClick={() => { fetchData(); }}
                  className="inline-flex items-center px-4 py-3 bg-gradient-to-r from-gray-500 to-slate-600 text-white font-medium rounded-xl hover:from-gray-600 hover:to-slate-700 transition-all duration-200 shadow-sm hover:shadow-md"
                >
                  <FiRefreshCw className="mr-2" size={16} />
                  Refresh
                </button>
                <button
                  onClick={() => setShowAddModal(true)}
                  className="inline-flex items-center px-4 py-3 bg-gradient-to-r from-purple-500 to-indigo-600 text-white font-medium rounded-xl hover:from-purple-600 hover:to-indigo-700 transition-all duration-200 shadow-sm hover:shadow-md"
                >
                  <FiPlus className="mr-2" size={16} />
                  Add Manual Plan
                </button>
              </div>
            </div>
          </div>
  
          {/* View Mode Toggle */}
          <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-200">
            <div className="flex space-x-2">
              <button
                onClick={() => setViewMode('all')}
                className={`px-4 py-2 rounded-lg font-medium transition-all duration-200 ${
                  viewMode === 'all' 
                    ? 'bg-indigo-100 text-indigo-700 border border-indigo-300' 
                    : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                }`}
              >
                All Tasks
              </button>
              <button
                onClick={() => setViewMode('manual')}
                className={`px-4 py-2 rounded-lg font-medium transition-all duration-200 ${
                  viewMode === 'manual' 
                    ? 'bg-blue-100 text-blue-700 border border-blue-300' 
                    : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                }`}
              >
                Manual Plans
              </button>
              <button
                onClick={() => setViewMode('auto')}
                className={`px-4 py-2 rounded-lg font-medium transition-all duration-200 ${
                  viewMode === 'auto' 
                    ? 'bg-green-100 text-green-700 border border-green-300' 
                    : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                }`}
              >
                Auto-Generated
              </button>
            </div>
          </div>
  
          {/* Date Filter & Stats */}
          <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200">
              <div className="flex items-center justify-between mb-4">
                <label htmlFor="date-filter" className="block text-sm font-medium text-gray-700">
                  Select Date
                </label>
                <FiCalendar className="text-gray-400" />
              </div>
              <input
                type="date"
                id="date-filter"
                value={selectedDate}
                onChange={(e) => setSelectedDate(e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
              />
            </div>
  
            {/* Stats Cards */}
            <div className="bg-gradient-to-br from-blue-500 to-indigo-600 p-6 rounded-xl text-white">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-blue-100">Total Bodies</p>
                  <p className="text-2xl font-bold">{stats.totalBodies}</p>
                </div>
                <FiUsers size={24} className="text-blue-200" />
              </div>
            </div>
  
            <div className="bg-gradient-to-br from-green-500 to-emerald-600 p-6 rounded-xl text-white">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-green-100">Completed</p>
                  <p className="text-2xl font-bold">{stats.completedItems}</p>
                </div>
                <FiCheckCircle size={24} className="text-green-200" />
              </div>
            </div>
  
            <div className="bg-gradient-to-br from-orange-500 to-red-600 p-6 rounded-xl text-white">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-orange-100">Pending</p>
                  <p className="text-2xl font-bold">{stats.pendingItems + stats.inProgressItems}</p>
                </div>
                <FiClock size={24} className="text-orange-200" />
              </div>
            </div>
          </div>
  
          {/* Filters */}
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Status Filter</label>
                <select
                  value={statusFilter}
                  onChange={(e) => setStatusFilter(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                >
                  <option value="all">All Statuses</option>
                  {statuses.map(status => (
                    <option key={status.value} value={status.value}>{status.label}</option>
                  ))}
                </select>
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Operation Filter</label>
                <select
                  value={operationFilter}
                  onChange={(e) => setOperationFilter(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                >
                  <option value="all">All Operations</option>
                  {operationTypes.map(op => (
                    <option key={op.value} value={op.value}>{op.label}</option>
                  ))}
                </select>
              </div>
              
              <div className="flex items-end">
                <label className="flex items-center">
                  <input
                    type="checkbox"
                    checked={showCompleted}
                    onChange={(e) => setShowCompleted(e.target.checked)}
                    className="rounded border-gray-300 text-indigo-600 focus:ring-indigo-500"
                  />
                  <span className="ml-2 text-sm text-gray-700">Show completed items</span>
                </label>
              </div>
            </div>
          </div>
  
          {/* Todo Items */}
          <div className="space-y-4">
            {/* Active Todos */}
            {activeTodos.length > 0 && (
              <div className="space-y-3">
                {activeTodos.map((item) => (
                  <TodoItem 
                    key={item.id} 
                    item={item} 
                    onEdit={setEditingItem}
                    onDelete={handleDeleteTodo}
                    onMarkGo={handleMarkGo}
                    onMarkPickedUp={handleMarkPickedUp}
                    getVendorName={getVendorName}
                    getStatusInfo={getStatusInfo}
                    getPriorityInfo={getPriorityInfo}
                    getOperationInfo={getOperationInfo}
                  />
                ))}
              </div>
            )}
  
            {/* Completed Todos */}
            {showCompleted && completedTodos.length > 0 && (
              <div>
                <h3 className="text-lg font-semibold text-gray-900 mb-3 flex items-center">
                  <FiCheckCircle className="mr-2 text-green-500" />
                  Completed ({completedTodos.length})
                </h3>
                <div className="space-y-3">
                  {completedTodos.map((item) => (
                    <TodoItem 
                      key={item.id} 
                      item={item} 
                      onEdit={setEditingItem}
                      onDelete={handleDeleteTodo}
                      onMarkGo={handleMarkGo}
                      onMarkPickedUp={handleMarkPickedUp}
                      getVendorName={getVendorName}
                      getStatusInfo={getStatusInfo}
                      getPriorityInfo={getPriorityInfo}
                      getOperationInfo={getOperationInfo}
                    />
                  ))}
                </div>
              </div>
            )}
  
            {/* Empty State */}
            {filteredTodos.length === 0 && (
              <div className="text-center py-12 bg-white rounded-xl border border-gray-200">
                <FiTruck className="mx-auto text-gray-400" size={48} />
                <h3 className="mt-4 text-lg font-medium text-gray-900">No collection tasks</h3>
                <p className="mt-2 text-gray-500">
                  {viewMode === 'auto' 
                    ? 'No auto-generated collection tasks found.' 
                    : 'No manual resource plans found for the selected filters.'}
                </p>
              </div>
            )}
          </div>
  
          {/* Completed Operations Summary */}
          <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-200">
            <div className="flex items-center space-x-3 mb-4">
              <div className="w-8 h-8 bg-gradient-to-br from-green-500 to-emerald-600 rounded-xl flex items-center justify-center">
                <FiCheckCircle className="text-white" size={16} />
              </div>
              <h3 className="text-lg font-semibold text-gray-900">Completed Operations Ready for Collection</h3>
              <span className="px-2 py-1 bg-green-100 text-green-800 text-sm rounded-full">
                {completedOperations.length} operations
              </span>
            </div>
            
            {completedOperations.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {completedOperations.slice(0, 6).map((op, index) => (
                  <div key={index} className={`border rounded-lg p-4 ${op.vendorTodoCreated ? 'bg-gray-50 border-gray-200' : 'bg-green-50 border-green-200'}`}>
                    <div className="flex justify-between items-start mb-2">
                      <span className="font-medium text-gray-800">{getMachineOperationName(op.operation)}</span>
                      <span className={`text-xs px-2 py-1 rounded ${
                        op.vendorTodoCreated 
                          ? 'bg-gray-200 text-gray-800' 
                          : 'bg-green-200 text-green-800'
                      }`}>
                        {op.vendorTodoCreated ? 'Task Created' : 'Ready for pickup'}
                      </span>
                    </div>
                    <div className="text-sm text-gray-700">
                      <div>PO: {op.poNumber}</div>
                      <div>Item: {op.itemDescription}</div>
                      <div>Vendor: {op.vendorName}</div>
                      <div>Qty: {op.quantity} {op.unit}</div>
                      {op.completedAt && (
                        <div className="text-xs text-gray-600 mt-1">
                          Completed: {op.completedAt.toDate?.().toLocaleDateString() || 'N/A'}
                        </div>
                      )}
                    </div>
                  </div>
                ))}
                {completedOperations.length > 6 && (
                  <div className="border border-gray-200 rounded-lg p-4 bg-gray-50 flex items-center justify-center">
                    <span className="text-gray-700">+{completedOperations.length - 6} more operations</span>
                  </div>
                )}
              </div>
            ) : (
              <p className="text-gray-500 text-center py-4">No completed operations waiting for collection</p>
            )}
          </div>
  
          {/* Add Todo Modal */}
          {showAddModal && (
            <AddTodoModal
              formData={formData}
              setFormData={setFormData}
              vendors={vendors}
              operationTypes={operationTypes}
              priorities={priorities}
              statuses={statuses}
              onAdd={handleAddTodo}
              onClose={() => setShowAddModal(false)}
              addVendorField={addVendorField}
              removeVendorField={removeVendorField}
              updateVendorField={updateVendorField}
            />
          )}
  
          {/* Edit Todo Modal */}
          {editingItem && (
            <EditTodoModal
              item={editingItem}
              vendors={vendors}
              operationTypes={operationTypes}
              priorities={priorities}
              statuses={statuses}
              onUpdate={handleUpdateTodo}
              onClose={() => setEditingItem(null)}
            />
          )}
        </div>
      )}
    </div>
  );
}